using System.Net;using Npgsql;using Xunit;
namespace BARANG.Core.IntegrationTests.Database;
#pragma warning disable CA1707,xUnit1051
[Collection(PostgreSqlDatabaseFixture.CollectionName)]public sealed class QualityFoundationTests(PostgreSqlDatabaseFixture database)
{
 [Fact]public async Task Migration_creates_qc_tables_permissions_rls_and_immutable_history(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT (SELECT count(*) FROM information_schema.tables WHERE table_schema='barang' AND table_name IN ('qc_templates','qc_template_criteria','qc_inspections','qc_criteria_results','defect_types','qc_defects','reproduction_requests','qc_history')),(SELECT count(*) FROM barang.permissions WHERE code IN ('qc.read','qc.inspect','qc.review','qc.manage','reproduction.manage')),(SELECT count(*) FROM pg_policies WHERE schemaname='barang' AND tablename IN ('qc_templates','qc_template_criteria','qc_inspections','qc_criteria_results','defect_types','qc_defects','reproduction_requests','qc_history')),has_table_privilege(current_user,'barang.qc_history','UPDATE'),has_table_privilege(current_user,'barang.qc_history','DELETE'),has_table_privilege(current_user,'barang.qc_criteria_results','UPDATE')";await using NpgsqlDataReader r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(8,r.GetInt64(0));Assert.Equal(5,r.GetInt64(1));Assert.Equal(8,r.GetInt64(2));Assert.False(r.GetBoolean(3));Assert.False(r.GetBoolean(4));Assert.False(r.GetBoolean(5));}
 [Fact]public async Task Quality_endpoints_reject_anonymous_callers(){using PostgreSqlCoreApiFactory f=new(database.ConnectionString);using HttpClient c=f.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync($"/api/v1/quality/inspections/{Guid.NewGuid()}")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/v1/quality/analytics?from=2026-01-01T00%3A00%3A00Z&to=2027-01-01T00%3A00%3A00Z")).StatusCode);}
 [Fact]public async Task Qc_rls_hides_rows_without_company_context(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using(NpgsqlCommand clear=c.CreateCommand()){clear.CommandText="RESET barang.company_id";await clear.ExecuteNonQueryAsync();}await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT count(*) FROM barang.qc_templates";Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
}
#pragma warning restore CA1707,xUnit1051
